    public PSDynaInstModelFolder[] getPSDynaInstModelFolders() {
        PSDynaInstModelFolder[] cur = this.dynaInstModelFolders;
        if (cur == null) {
            PSDynaInstModelFolder instModelFolder;
            PSDynaInstModelFolder instModelFolder2;
            ArrayList<PSDynaInstModelFolder> instModelFolderList = new ArrayList<PSDynaInstModelFolder>();
            if (!StringHelper.isNullOrEmpty((String)this.getConfPSModelFolderPath())) {
                instModelFolder2 = new PSDynaInstModelFolder();
                instModelFolder2.modelPath = this.getConfPSModelFolderPath();
                instModelFolderList.add(instModelFolder2);
            }
            if (this.getPPSDevSlnSysDynaInstRefList() != null) {
                for (PSDevSlnSysDynaInstRef psDevSlnSysDynaInstRef : this.getPPSDevSlnSysDynaInstRefList()) {
                    instModelFolder = new PSDynaInstModelFolder();
                    instModelFolder.modelPath = psDevSlnSysDynaInstRef.getINSTMODELPATH();
                    instModelFolder.dynaTemplId = psDevSlnSysDynaInstRef.getPSDEVSLNSYSDYNAINSTREFID();
                    instModelFolder.dynaTemplName = psDevSlnSysDynaInstRef.getPSDEVSLNSYSDYNAINSTREFNAME();
                    instModelFolderList.add(instModelFolder);
                }
            }
            if (!StringHelper.isNullOrEmpty((String)this.getPPSDynaInstFolderPath())) {
                instModelFolder2 = new PSDynaInstModelFolder();
                instModelFolder2.modelPath = this.getPPSDynaInstFolderPath();
                instModelFolder2.dynaInstId = this.getPPSDynaInstId();
                instModelFolderList.add(instModelFolder2);
            }
            if (this.getPSDevSlnSysDynaInstRefList() != null) {
                for (PSDevSlnSysDynaInstRef psDevSlnSysDynaInstRef : this.getPSDevSlnSysDynaInstRefList()) {
                    instModelFolder = new PSDynaInstModelFolder();
                    instModelFolder.modelPath = psDevSlnSysDynaInstRef.getINSTMODELPATH();
                    instModelFolder.dynaTemplId = psDevSlnSysDynaInstRef.getPSDEVSLNSYSDYNAINSTREFID();
                    instModelFolder.dynaTemplName = psDevSlnSysDynaInstRef.getPSDEVSLNSYSDYNAINSTREFNAME();
                    instModelFolderList.add(instModelFolder);
                }
            }
            if (!StringHelper.isNullOrEmpty((String)this.getPSDynaInstFolderPath())) {
                instModelFolder2 = new PSDynaInstModelFolder();
                instModelFolder2.modelPath = this.getPSDynaInstFolderPath();
                instModelFolder2.dynaInstId = this.getPSDynaInstId();
                instModelFolderList.add(instModelFolder2);
            }
            this.dynaInstModelFolders = cur = instModelFolderList.toArray(new PSDynaInstModelFolder[instModelFolderList.size()]);
        }
        return cur;
    }

    protected Object doDynaInstWork(IDynaInstWork iDynaInstWork, Object objArg) throws Exception {
        boolean bOpenSession = false;
        if (PSModelServiceSession.getCurrent((boolean)true) == null) {
            PSModelServiceSession psModelServiceSession = PSModelServiceSession.open((boolean)true);
            psModelServiceSession.setPSModelFolderPath(this.strPSModelFolderPath);
            psModelServiceSession.setConfPSModelFolderPath(this.strConfPSModelFolderPath);
            psModelServiceSession.setPSDynaInstId(this.strPSDynaInstId);
            psModelServiceSession.setPSDynaInstFolderPath(this.strPSDynaInstFolderPath);
            psModelServiceSession.setPPSDynaInstId(this.strPPSDynaInstId);
            psModelServiceSession.setPPSDynaInstFolderPath(this.strPPSDynaInstFolderPath);
            psModelServiceSession.setPSDynaInstModelFolders(this.getPSDynaInstModelFolders());
            bOpenSession = true;
        }
        try {
            Object objRet = iDynaInstWork.execute(objArg);
            if (bOpenSession) {
                PSModelServiceSession.close((boolean)true);
            }
            return objRet;
        }
        catch (Exception ex) {
            log.error((Object)String.format("\u6267\u884c\u52a8\u6001\u5b9e\u4f8b\u4f5c\u4e1a\u53d1\u751f\u5f02\u5e38\uff0c%1$s", ex.getMessage()), (Throwable)ex);
            if (bOpenSession) {
                PSModelServiceSession.close((boolean)false);
            }
            throw ex;
        }
    }

    protected CallResult doDynaInstWork2(IDynaInstWork iDynaInstWork, Object objArg) {
        return this.doDynaInstWork2(iDynaInstWork, objArg, null);
    }

    protected CallResult doDynaInstWork2(IDynaInstWork iDynaInstWork, Object objArg, String strTag) {
        CallResult callResult = new CallResult();
        boolean bOpenSession = false;
        try {
            if (PSModelServiceSession.getCurrent((boolean)true) == null) {
                PSModelServiceSession psModelServiceSession = PSModelServiceSession.open((boolean)true);
                psModelServiceSession.setPSModelFolderPath(this.strPSModelFolderPath);
                psModelServiceSession.setConfPSModelFolderPath(this.strConfPSModelFolderPath);
                psModelServiceSession.setPSDynaInstId(this.strPSDynaInstId);
                psModelServiceSession.setPSDynaInstFolderPath(this.strPSDynaInstFolderPath);
                psModelServiceSession.setPPSDynaInstId(this.strPPSDynaInstId);
                psModelServiceSession.setPPSDynaInstFolderPath(this.strPPSDynaInstFolderPath);
                psModelServiceSession.setPSDynaInstModelFolders(this.getPSDynaInstModelFolders());
                bOpenSession = true;
            }
            long nStartTime = System.currentTimeMillis();
            callResult.setUserObject(iDynaInstWork.execute(objArg));
            nStartTime = System.currentTimeMillis() - nStartTime;
            if (StringHelper.isNullOrEmpty((String)strTag)) {
                log.debug((Object)String.format("\u52a8\u6001\u5b9e\u4f8b\u4f5c\u4e1a\u8017\u65f6[%1$s]ms", nStartTime));
            } else {
                log.debug((Object)String.format("\u52a8\u6001\u5b9e\u4f8b\u4f5c\u4e1a[%2$s]\u8017\u65f6[%1$s]ms", nStartTime, strTag));
            }
            if (bOpenSession) {
                PSModelServiceSession.close((boolean)true);
            }
            return callResult;
        }
        catch (Exception ex) {
            log.error((Object)String.format("\u6267\u884c\u52a8\u6001\u5b9e\u4f8b\u4f5c\u4e1a\u53d1\u751f\u5f02\u5e38\uff0c%1$s", ex.getMessage()), (Throwable)ex);
            if (bOpenSession) {
                PSModelServiceSession.close((boolean)false);
            }
            callResult.setRetCode(1);
            callResult.setErrorInfo(ex.getMessage());
            return callResult;
        }
    }

